description:
Write the calculation inside `ImGuiListClipper`:

```cpp
struct Range { int start; int end; };    // draw items start .. end-1

Range visibleRange(int itemCount, float itemHeight, float scrollY, float viewHeight);
float contentHeight(int itemCount, float itemHeight);
bool shouldFollow(float scrollY, float scrollMaxY);
```

- `visibleRange`: the first visible item is `floor(scrollY / itemHeight)`; the end is `ceil((scrollY + viewHeight) / itemHeight)`. Clamp both to `0 .. itemCount`. An item height of 0 or less, or no items, gives `{0, 0}`.
- `contentHeight`: the total height the scroll bar must cover.
- `shouldFollow`: a log keeps following new lines only if it was scrolled to the bottom: `scrollY >= scrollMaxY - 1` (allowing one pixel of rounding).

```
visibleRange(100000, 20, 1000, 300) == { 50, 65 }
```

starter.solution.cpp:
#include <cmath>

struct Range { int start; int end; };

Range visibleRange(int itemCount, float itemHeight, float scrollY, float viewHeight) { return { 0, itemCount }; }
float contentHeight(int itemCount, float itemHeight) { return 0; }
bool shouldFollow(float scrollY, float scrollMaxY) { return true; }

solution.solution.cpp:
#include <cmath>

struct Range { int start; int end; };

Range visibleRange(int itemCount, float itemHeight, float scrollY, float viewHeight)
{
    if (itemCount <= 0 || itemHeight <= 0.0f) return { 0, 0 };
    int start{ static_cast<int>(std::floor(scrollY / itemHeight)) };
    int end{ static_cast<int>(std::ceil((scrollY + viewHeight) / itemHeight)) };
    if (start < 0) start = 0;
    if (start > itemCount) start = itemCount;
    if (end < start) end = start;
    if (end > itemCount) end = itemCount;
    return { start, end };
}

float contentHeight(int itemCount, float itemHeight)
{
    return itemCount > 0 && itemHeight > 0.0f ? static_cast<float>(itemCount) * itemHeight : 0.0f;
}

bool shouldFollow(float scrollY, float scrollMaxY)
{
    return scrollY >= scrollMaxY - 1.0f;
}

unitTests:
TEST("the example") { const Range r = visibleRange(100000, 20, 1000, 300); CHECK_EQ(r.start, 50); CHECK_EQ(r.end, 65); }
TEST("part items at both ends") { const Range r = visibleRange(100, 20, 1010, 300); CHECK_EQ(r.start, 50); CHECK_EQ(r.end, 66); }
TEST("top") { const Range r = visibleRange(10, 20, 0, 300); CHECK_EQ(r.start, 0); CHECK_EQ(r.end, 10); }
TEST("bottom is clamped") { const Range r = visibleRange(100, 20, 1990, 300); CHECK_EQ(r.start, 99); CHECK_EQ(r.end, 100); }
TEST("nothing") { const Range r = visibleRange(0, 20, 0, 300); CHECK_EQ(r.start, 0); CHECK_EQ(r.end, 0); const Range z = visibleRange(10, 0, 0, 300); CHECK_EQ(z.end, 0); }
TEST("content height") { CHECK_NEAR(contentHeight(100000, 20), 2000000.0, 1e-3); CHECK_NEAR(contentHeight(0, 20), 0.0, 1e-9); }
TEST("follow") { CHECK(shouldFollow(500, 500)); CHECK(shouldFollow(499.5f, 500)); CHECK(!shouldFollow(300, 500)); CHECK(shouldFollow(0, 0)); }

